let additionCurrent;let additionReturnFocus;const additionVisualDrafts=new Map();const additionLookup=new Map(workflowAdditionFrames.map(s=>[s.id,s]));
const additionEscape=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function additionNavigate(id,provider){if(new URLSearchParams(location.search).has('kind'))return;if(provider){const u=new URL(location.href);u.searchParams.set('provider',provider);history.replaceState({},'',u);}if(additionLookup.get(id)?.layout==='sheet'&&additionCurrent?.layout==='page')additionReturnFocus={id:additionCurrent.id,target:id};if(additionCurrent?.form&&id===additionCurrent.actions[0]?.target&&additionLookup.get(id)?.toast){additionVisualDrafts.set(id,[...document.querySelectorAll('.addition-form input,.addition-form textarea')].map(e=>({name:e.name,type:e.type,value:e.type==='password'?'':e.value,checked:e.checked})));}if(additionLookup.has(id)){const u=new URL(location.href);u.searchParams.set('state',id);history.pushState({},'',u);additionRender(id);}else location.href='workflow-map.html#'+encodeURIComponent(id);}
function additionRender(id){const original=additionLookup.get(id)||additionLookup.get('account-entry');const s={...original};const providerNames={email:'Почта',apple:'Apple',telegram:'Telegram',google:'Google'};const provider=providerNames[new URLSearchParams(location.search).get('provider')]||'Почта';if(s.id==='provider-link-confirm')s.body=s.body.replace('<strong>Почта</strong>','<strong>'+provider+'</strong>');additionCurrent=s;document.title=s.title+' · workflow design';const icon=(name)=>'<i data-lucide="'+name+'" class="icon" aria-hidden="true"></i>';const back=s.parent?'<button type="button" class="icon-button" aria-label="'+(s.layout==='sheet'?'Закрыть':'Назад')+'" data-go="'+s.parent+'">'+icon(s.layout==='sheet'?'x':'arrow-left')+'</button>':'<span class="head-slot" aria-hidden="true"></span>';const title='<h2 id="addition-title">'+additionEscape(s.title)+'</h2>';const controls=s.actions.map(a=>'<button type="button" class="'+a.variant+'" data-go="'+a.target+'">'+additionEscape(a.label)+'</button>').join('');const form=s.form?'form':'div';const content='<'+form+' class="addition-form" novalidate><div class="sheet-body addition-body">'+s.body+'</div>'+(controls?'<div class="addition-actions '+(s.actions.length===2?'action-pair':'')+'">'+controls+'</div>':'')+'</'+form+'>';const main=s.layout==='sheet'?'<div class="addition-origin" aria-hidden="true"></div><div class="shade"><section class="sheet" role="dialog" aria-modal="true" aria-labelledby="addition-title"><div class="sheet-head">'+title+back+'</div>'+content+'</section></div>':'<header class="full-head addition-head">'+back+title+'<span class="head-slot" aria-hidden="true"></span></header>'+content;document.getElementById('addition-phone').innerHTML='<div class="status"><strong>9:41</strong><span>LTE</span></div>'+main+(s.toast?'<div class="toast" role="status">'+icon('check')+additionEscape(s.toast)+'</div>':'');document.getElementById('addition-note').textContent='Design for review · '+s.note;document.body.dataset.previewReady='true';document.body.dataset.selectedDesignState=s.id;const draft=additionVisualDrafts.get(s.id);if(draft){for(const item of draft){const fields=[...document.querySelectorAll('.addition-form input,.addition-form textarea')].filter(e=>e.name===item.name);for(const e of fields){if(e.type==='radio')e.checked=e.value===item.value&&item.checked;else e.value=item.value;}}const rating=draft.find(e=>e.name==='rating');if(rating?.value)document.querySelector('[data-rating="'+rating.value+'"]')?.click();}if(s.toast)document.querySelectorAll('.addition-form input,.addition-form textarea,.addition-form [data-rating]').forEach(e=>e.disabled=true);window.lucide?.createIcons();if(!new URLSearchParams(location.search).has('kind')){const title=document.querySelector('.addition-head h2,.sheet-head h2');title?.setAttribute('tabindex','-1');if(additionReturnFocus?.id===s.id){document.querySelector('[data-go="'+additionReturnFocus.target+'"]')?.focus();additionReturnFocus=null;}else title?.focus();}}
document.addEventListener('submit',e=>e.preventDefault());document.addEventListener('click',e=>{const star=e.target.closest('[data-rating]');if(star){const n=Number(star.dataset.rating),group=star.closest('.rating-choices');group.querySelectorAll('button').forEach(b=>{b.setAttribute('aria-checked',String(Number(b.dataset.rating)===n));b.tabIndex=Number(b.dataset.rating)===n?0:-1;b.classList.toggle('active',Number(b.dataset.rating)<=n)});group.parentElement.querySelector('.rating-value').value=String(n);group.removeAttribute('aria-invalid');group.parentElement.querySelector('.rating-error')?.remove();return}const button=e.target.closest('[data-go]');if(!button)return;const form=button.closest('form');if(form&&button.classList.contains('primary')&&!additionCurrent.toast){if(!form.reportValidity())return;const value=form.querySelector('.rating-value');if(value&&!value.value){const group=form.querySelector('.rating-choices');group.setAttribute('aria-invalid','true');let error=form.querySelector('.rating-error');if(!error){error=document.createElement('p');error.className='field-error rating-error';error.setAttribute('role','alert');error.textContent='Выберите оценку.';group.after(error);}form.querySelector('[data-rating="1"]').focus();return}}additionNavigate(button.dataset.go,button.dataset.provider)});
document.addEventListener('keydown',e=>{const dialog=document.querySelector('[role=dialog]');if(dialog&&e.key==='Tab'){const items=[...dialog.querySelectorAll('button:not([disabled]),input:not([type=hidden]),textarea,[tabindex="0"]')].filter(x=>x.getClientRects().length);if(items.length&&((!items.includes(document.activeElement))||(e.shiftKey&&document.activeElement===items[0])||(!e.shiftKey&&document.activeElement===items.at(-1)))){e.preventDefault();(e.shiftKey?items.at(-1):items[0]).focus();}}if(e.key==='Escape'&&additionCurrent.parent){e.preventDefault();additionNavigate(additionCurrent.parent)}const b=e.target.closest('[data-rating]');if(!b)return;const keys=['ArrowLeft','ArrowDown','ArrowRight','ArrowUp','Home','End'];if(!keys.includes(e.key))return;e.preventDefault();let n=Number(b.dataset.rating);n=e.key==='Home'?1:e.key==='End'?5:Math.max(1,Math.min(5,n+(['ArrowLeft','ArrowUp'].includes(e.key)?-1:1)));const next=b.parentElement.querySelector('[data-rating="'+n+'"]');next.click();next.focus()});
document.addEventListener('input',e=>{if(e.target.getAttribute('aria-label')!=='Найти участника')return;const q=e.target.value.trim().toLowerCase();document.querySelectorAll('.supplemental-row').forEach(row=>row.hidden=!row.textContent.toLowerCase().includes(q));const empty=document.querySelector('.empty-members');if(empty)empty.hidden=[...document.querySelectorAll('.supplemental-row')].some(row=>!row.hidden)});
window.addEventListener('popstate',()=>additionRender(new URLSearchParams(location.search).get('state')));additionRender(new URLSearchParams(location.search).get('state'));
